// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/inter";
import "@fontsource/noto-sans-kr";

export const inter = { variable: "" };
export const notoSansKR = { variable: "" };

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const PARALLAX_LERP = 0.045;

/**
 * Drives `--drm-px` / `--drm-py` (each −1…1) on the referenced element — the
 * weightless depth of the cloud sky. styles.css multiplies these into
 * capped translations at three depths: the far sky barely moves, the middle
 * layer carries the drift, the nearest puffs read at arm's length. The lerp
 * is deliberately slower than a tracking parallax (0.045 vs the usual 0.08):
 * clouds do not chase the pointer, they settle after it.
 *
 * Fine pointers only — on touch the layers simply rest (the ambient cloud-bob
 * animation carries the life instead), and under reduced motion this hook
 * does nothing; the CSS fallback for both variables is 0.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = PARALLAX_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--drm-px", x.toFixed(4));
      el.style.setProperty("--drm-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
      ty = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--drm-px");
      el.style.removeProperty("--drm-py");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Drives a 0→1 scroll progress for a pinned chashitsu (tea-preparation
 * scene), written to the element as the `--ch-scrub` custom property. The
 * chasen whisk consumes it in CSS:
 *   stroke-dashoffset: calc(1 - var(--ch-scrub, 1))
 * on pathLength=1 bamboo-tine paths — so the whisk draws exactly as far as
 * the guest has scrolled, and the bowl's matcha surface blooms in only as
 * the preparation completes. The whole ceremony is paced so the whisk never
 * moves faster than the hand that summoned it.
 *
 * Discipline (rubric gate G3):
 * - All geometry is measured inside rAF: one getBoundingClientRect read,
 *   then one custom-property write — read before write, no layout thrash.
 * - The raw progress is lerp-smoothed with a dt-normalized factor
 *   (1 - 0.88^(dt/16.7)), so a 120Hz display does not scrub twice as fast
 *   as a 60Hz one. Half-life ≈ 5.4 frames.
 * - An IntersectionObserver starts/stops the loop, so an offscreen
 *   chashitsu costs zero frames. A visibilitychange listener also stops it
 *   when the tab is hidden.
 * - Disabled (reduced motion) or never mounted (no JS): the hook writes
 *   `--ch-scrub: 1` once and the CSS default of 1 leaves every tine drawn
 *   and the bowl full — a completed preparation, statically waiting.
 */
export function useScrollProgress<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    if (disabled) {
      el.style.setProperty("--ch-scrub", "1");
      return;
    }

    let raf = 0;
    let last = 0;
    let value: number | null = null;

    const frame = (now: number) => {
      raf = requestAnimationFrame(frame);
      const dt = Math.min(Math.max(now - last, 1), 48);
      last = now;

      // Read phase: one rect, one viewport height.
      const rect = el.getBoundingClientRect();
      const vh = window.innerHeight || 1;

      // The scrub runs from "scene center at 62% of the viewport" across
      // 90% of the scene's height, capped at ~1.2 viewports so tall
      // single-column (mobile) chashitsu still finish while in view.
      const center = rect.top + rect.height / 2;
      const span = Math.max(Math.min(rect.height * 0.9, vh * 1.2), 1);
      const raw = (vh * 0.62 - center) / span;
      const target = Math.min(1, Math.max(0, raw));

      if (value === null) {
        value = target; // first frame: no animated catch-up flash
      } else {
        value += (target - value) * (1 - Math.pow(0.88, dt / 16.7));
        if (Math.abs(target - value) < 0.0005) value = target;
      }

      // Write phase.
      el.style.setProperty("--ch-scrub", value.toFixed(4));
    };

    const start = () => {
      if (raf) return;
      last = performance.now();
      raf = requestAnimationFrame(frame);
    };
    const stop = () => {
      if (!raf) return;
      cancelAnimationFrame(raf);
      raf = 0;
    };

    const onVisibility = () => {
      if (document.hidden) stop();
      else start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    if (!("IntersectionObserver" in window)) {
      start();
      return () => {
        stop();
        document.removeEventListener("visibilitychange", onVisibility);
      };
    }

    const io = new IntersectionObserver(
      (hits) => {
        for (const hit of hits) {
          if (hit.isIntersecting) start();
          else stop();
        }
      },
      { rootMargin: "25% 0px 25% 0px" },
    );
    io.observe(el);

    return () => {
      stop();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [disabled]);

  return ref;
}

/* ==========================================================================
   FLOW 흐름 — river of words · kinetic-typography
   sky / paper / drift · letters flow like water
   Scoped by convention to .flow-root; classes prefixed flow-.
   ========================================================================== */

.flow-root {
  /* -- palette ---------------------------------------------------------------
     A sky-and-paper palette. The accent is bright but low-contrast against
     the pale sky, so it is decorative-only for text; body copy stays on the
     deep ink tones which clear AA comfortably. */
  --flow-bg: #f0f9ff;          /* sky at rest — page surface */
  --flow-bg-deep: #e0f2fe;     /* paper at depth — verse well */
  --flow-ink: #0c4a6e;         /* primary text — 8.87:1 on sky (AAA) */
  --flow-ink-soft: #0369a1;    /* secondary text — 5.57:1 on sky (AA), 5.17:1 on paper (AA) */
  --flow-accent: #0ea5e9;      /* accent — DECORATIVE ONLY (2.60:1 on sky), large/glyph use */
  --flow-accent-press: #075985;/* solid fills, ink-on-accent: 7.09:1 on sky (AAA), white-on-it 7.74:1 */
  --flow-accent-soft: rgba(14, 165, 233, 0.15);  /* hairlines, never text */
  --flow-accent-glass: rgba(14, 165, 233, 0.06); /* card surface wash */
  --flow-font: "Inter", "Noto Sans KR", sans-serif;
  --flow-font-ko: "Noto Sans KR", "Inter", sans-serif;

  /* -- spacing (4px baseline) ---------------------------------------------- */
  --flow-space-1: 0.25rem;   /*  4px */
  --flow-space-2: 0.5rem;    /*  8px */
  --flow-space-3: 0.75rem;   /* 12px */
  --flow-space-4: 1rem;      /* 16px */
  --flow-space-6: 1.5rem;    /* 24px */
  --flow-space-8: 2rem;      /* 32px */
  --flow-space-12: 3rem;     /* 48px */
  --flow-space-16: 4rem;     /* 64px */
  --flow-space-24: 6rem;     /* 96px */

  /* -- motion ---------------------------------------------------------------
     Two curves: drift for the slow entrance/reveal of letters, spring for the
     snappy micro-interactions on cards and words. */
  --flow-ease-drift:  cubic-bezier(0.16, 1, 0.3, 1);   /* strong ease-out — entrance */
  --flow-ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1); /* soft back — hover/press */

  position: relative;
  min-height: 100vh;
  background: linear-gradient(180deg, var(--flow-bg) 0%, var(--flow-bg-deep) 100%);
  color: var(--flow-ink);
  font-family: var(--flow-font);
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.75;
  overflow-x: hidden;
  overflow-x: clip;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

.flow-root,
.flow-root *,
.flow-root *::before,
.flow-root *::after {
  box-sizing: border-box;
}

.flow-root h1,
.flow-root h2,
.flow-root h3,
.flow-root p {
  margin: 0;
}

/* Korean is first-class: its own typeface and rhythm, words kept whole. */
.flow-root :lang(ko) {
  font-family: var(--flow-font-ko);
  letter-spacing: 0;
  line-height: 1.8;
  word-break: keep-all;
  word-wrap: break-word;
}

.flow-root ::selection {
  background: var(--flow-accent);
  color: #fff;
}

.flow-root :focus-visible {
  outline: 2px solid var(--flow-accent-press);
  outline-offset: 3px;
  border-radius: 3px;
  box-shadow: 0 0 0 6px rgba(7, 89, 133, 0.15);
}

/* ==========================================================================
   Water surface — three layered ambient textures, all pure CSS:
   1. slow-drifting SVG wave lines (the current, set in feTurbulence-free CSS)
   2. two concentric caustic blooms that breathe at different rates
   3. a vertical depth wash that holds the whole sky together
   ========================================================================== */

.flow-root::before {
  content: "";
  position: fixed;
  inset: -20%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(40% 30% at 30% 20%, rgba(14, 165, 233, 0.07), transparent 60%),
    radial-gradient(45% 35% at 75% 70%, rgba(7, 89, 133, 0.06), transparent 60%),
    radial-gradient(50% 40% at 50% 110%, rgba(14, 165, 233, 0.05), transparent 65%);
  animation: flow-surface 18s var(--flow-ease-drift) infinite alternate;
}

/* a second, slower current at a different period so the surface never loops */
.flow-root::after {
  content: "";
  position: fixed;
  inset: -25%;
  z-index: 0;
  pointer-events: none;
  /* repeating horizontal wave lines — the implied current of the river */
  background-image: repeating-linear-gradient(
    91deg,
    transparent 0px,
    transparent 38px,
    rgba(14, 165, 233, 0.04) 39px,
    rgba(14, 165, 233, 0.04) 40px,
    transparent 41px,
    transparent 90px
  );
  background-size: 320px 320px;
  opacity: 0.7;
  animation: flow-current 23s var(--flow-ease-drift) infinite alternate;
}

@keyframes flow-surface {
  to { transform: translate3d(2%, -1%, 0) scale(1.04); }
}
@keyframes flow-current {
  to { transform: translate3d(-3%, 1.5%, 0) scale(1.05); }
}

@media (prefers-reduced-motion: reduce) {
  .flow-root::before,
  .flow-root::after { animation: none; }
}

/* ==========================================================================
   Reveal gating
   ========================================================================== */

.flow-js [data-reveal] {
  opacity: 0;
  transform: translateY(24px);
  transition:
    opacity 900ms var(--flow-ease-drift),
    transform 900ms var(--flow-ease-drift);
}
.flow-js [data-reveal].is-visible { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  .flow-js [data-reveal] { opacity: 1; transform: none; transition: none; }
}

/* ==========================================================================
   Pointer-parallax layer — the whole hero leans gently toward the cursor
   ========================================================================== */

.flow-parallax {
  position: relative;
  z-index: 1;
  transition: transform 600ms var(--flow-ease-drift);
  will-change: transform;
}
@media (prefers-reduced-motion: reduce) {
  .flow-parallax { transform: none !important; transition: none; }
}

/* ==========================================================================
   Hero — the arrival; letters drift in like a current
   ========================================================================== */

.flow-hero {
  position: relative;
  z-index: 1;
  padding:
    clamp(80px, 18vh, 160px)
    clamp(20px, 5vw, 60px)
    clamp(40px, 8vh, 80px);
  text-align: center;
}

.flow-kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.24em;
  color: var(--flow-accent-press);
  margin: 0 0 var(--flow-space-8);
}
.flow-kicker :lang(ko) {
  text-transform: none;
  letter-spacing: 0;
}

.flow-title {
  font-weight: 700;
  font-size: clamp(4rem, 14vw, 10rem);
  line-height: 0.9;
  letter-spacing: -0.03em;          /* display: tight tracking for the wordmark */
  margin: 0 0 var(--flow-space-6);
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.02em;
  text-wrap: balance;
}

/* char-split-reveal: each glyph drifts in from the side, staggered */
.flow-glyph {
  display: inline-block;
  opacity: 0;
  transform: translateX(-40px) skewX(-8deg);
}
.flow-js .flow-glyph {
  animation: flow-glyph-in 1100ms var(--flow-ease-drift) both;
  animation-delay: calc(var(--flow-i, 0) * 140ms + 200ms);
}
@keyframes flow-glyph-in {
  to { opacity: 1; transform: translateX(0) skewX(0); }
}
@media (prefers-reduced-motion: reduce) {
  .flow-glyph { opacity: 1; transform: none; animation: none; }
}

.flow-title__ko {
  display: block;
  width: 100%;
  font-size: 0.32em;
  color: var(--flow-ink-soft);
  margin-top: var(--flow-space-2);
  font-weight: 500;
  letter-spacing: 0;                /* Korean: no tightened tracking */
}

.flow-sub {
  max-width: 540px;
  margin: 0 auto;
  color: var(--flow-ink-soft);
  font-size: clamp(0.95rem, 1.6vw, 1.15rem);
  line-height: 1.7;
  text-wrap: pretty;
}

/* ==========================================================================
   scroll-scrub-pinned: the verse section
   ========================================================================== */

.flow-verse {
  position: sticky;
  top: 0;
  min-height: 100vh;
  min-height: 100svh;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(40px, 8vh, 80px) clamp(20px, 5vw, 60px);
  background:
    radial-gradient(80% 60% at 50% 50%, rgba(14, 165, 233, 0.08), transparent 70%),
    radial-gradient(60% 50% at 50% 100%, rgba(7, 89, 133, 0.06), transparent 70%),
    var(--flow-bg-deep);
  border-top: 1px solid var(--flow-accent-soft);
  border-bottom: 1px solid var(--flow-accent-soft);
}

.flow-verse__inner {
  max-width: 680px;
  text-align: center;
}

.flow-verse__title {
  font-size: clamp(1.8rem, 4.5vw, 3rem);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.02em;          /* large display heading */
  margin: var(--flow-space-12) 0;
  color: var(--flow-ink);
  text-wrap: balance;
}

/* The stream of words flows horizontally, driven by --flow-scrub */
.flow-verse__stream {
  display: flex;
  gap: clamp(16px, 3vw, 32px);
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: var(--flow-space-12);
}

.flow-verse__word {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  font-weight: 500;
  color: var(--flow-accent-press);
  margin: 0;
  letter-spacing: 0;
  opacity: calc(0.3 + var(--flow-scrub, 0.5) * 0.7);
  transform: translateY(calc((1 - var(--flow-scrub, 0.5)) * 20px));
  transition:
    opacity 200ms var(--flow-ease-drift),
    transform 200ms var(--flow-ease-drift);
}

.flow-verse__en {
  font-size: clamp(0.9rem, 1.5vw, 1.05rem);
  color: var(--flow-ink-soft);
  margin: 0;
  line-height: 1.6;
  text-wrap: pretty;
}
.flow-verse__en em {
  font-style: italic;
  letter-spacing: 0.01em;
}

/* ==========================================================================
   Features — cards with visual hierarchy, not bare text columns
   Each card: a soft accent wash, layered shadow, and a spring lift on hover.
   ========================================================================== */

.flow-features {
  position: relative;
  z-index: 1;
  padding: clamp(60px, 12vh, 120px) clamp(20px, 5vw, 60px);
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: clamp(24px, 4vw, 40px);
  max-width: 1000px;
  margin: 0 auto;
}

.flow-feature {
  position: relative;
  padding: var(--flow-space-8) var(--flow-space-6) var(--flow-space-6);
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.75) 0%, rgba(240, 249, 255, 0.55) 100%);
  border: 1px solid var(--flow-accent-soft);
  backdrop-filter: blur(8px) saturate(140%);
  -webkit-backdrop-filter: blur(8px) saturate(140%);
  box-shadow:
    0 1px 2px  rgba(7, 89, 133, 0.05),   /* ambient — surface contact */
    0 8px 18px rgba(7, 89, 133, 0.08),   /* key — primary cast */
    0 24px 48px rgba(7, 89, 133, 0.06);  /* contact — far diffusion */
  transition:
    transform 280ms var(--flow-ease-spring),
    box-shadow 280ms var(--flow-ease-drift),
    border-color 200ms var(--flow-ease-drift);
}

/* a soft accent wash behind the heading — the implied light source */
.flow-feature::before {
  content: "";
  position: absolute;
  top: -1px;
  left: var(--flow-space-6);
  right: var(--flow-space-6);
  height: 3px;
  border-radius: 3px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--flow-accent) 30%,
    var(--flow-accent-press) 70%,
    transparent 100%
  );
  opacity: 0.55;
  transition: opacity 280ms var(--flow-ease-drift);
}

.flow-feature:hover {
  transform: translateY(-4px);
  border-color: rgba(14, 165, 233, 0.32);
  box-shadow:
    0 2px 4px  rgba(7, 89, 133, 0.06),
    0 14px 28px rgba(7, 89, 133, 0.12),
    0 36px 64px rgba(7, 89, 133, 0.08);
}
.flow-feature:hover::before { opacity: 1; }

.flow-feature:focus-within {
  border-color: rgba(14, 165, 233, 0.36);
}

.flow-feature__h {
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.3;
  margin: 0 0 var(--flow-space-3);
  color: var(--flow-ink);
}
.flow-feature__h :lang(ko) {
  color: var(--flow-accent-press);
  letter-spacing: 0;
}

.flow-feature__p {
  margin: 0;
  color: var(--flow-ink-soft);
  font-size: 0.95rem;
  line-height: 1.65;
  text-wrap: pretty;
}

/* ==========================================================================
   Footer
   ========================================================================== */

.flow-foot {
  position: relative;
  z-index: 1;
  padding: clamp(48px, 10vh, 80px) clamp(20px, 5vw, 60px);
  text-align: center;
  border-top: 1px solid var(--flow-accent-soft);
  color: var(--flow-ink-soft);
  font-size: 0.82rem;
  line-height: 1.7;
}
.flow-foot p { margin: 0 0 var(--flow-space-2); }

/* ==========================================================================
   Composition — responsive drifts at three breakpoints
   ========================================================================== */

@media (max-width: 900px) {
  .flow-features {
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  }
  .flow-title {
    letter-spacing: -0.02em;
  }
}

@media (max-width: 720px) {
  .flow-feature {
    padding: var(--flow-space-6) var(--flow-space-4);
  }
  .flow-feature::before {
    left: var(--flow-space-4);
    right: var(--flow-space-4);
  }
  .flow-verse__stream {
    gap: clamp(12px, 2.5vw, 20px);
  }
}

@media (max-width: 480px) {
  .flow-kicker {
    font-size: 0.66rem;
    letter-spacing: 0.2em;
    margin-bottom: var(--flow-space-6);
  }
  .flow-title__ko {
